// CreateTableWithDBType creates the Project_Journal_Line table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *ProjectJournalLine) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := tables.CompanyTable(company, ProjectJournalLineTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetProjectJournalLinePostgresTableSchema()
	} else {
		schema = GetProjectJournalLineTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Project_Journal_Line table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *ProjectJournalLine) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := tables.CompanyTable(company, ProjectJournalLineTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (journal_template_name, journal_batch_name, line_no)`,
		fmt.Sprintf("%s$Project_Journal_Line$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (journal_template_name, journal_batch_name, type, no, unit_of_measure_code, work_type_code)`,
		fmt.Sprintf("%s$Project_Journal_Line$type_no", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index type_no: %w", err)
	}
	var keys []sift.Key
	for _, spec := range projectJournalLineSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, ProjectJournalLineTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, ProjectJournalLineTableName, keys)
}

// projectJournalLineSIFTSpecs are the table's keys with sum_index_fields
func projectJournalLineSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *ProjectJournalLine) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := tables.CompanyTable(t.company, ProjectJournalLineTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range projectJournalLineSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, ProjectJournalLineTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: ProjectJournalLineTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, ProjectJournalLineTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

